    ],
    "conclusions": [
      "The pressure satisfies p_tt = c² p_xx [printed page 3, equation (1.7)].",
      "This pressure equation is obtained from the acoustic system (1.5) by differentiating its first equation in t and its second equation in x, then eliminating the mixed derivatives of u [printed page 3, paragraph immediately following (1.7)].",
      "The source identifies equation (1.7) as hyperbolic under the standard classification of second-order linear equations [printed page 3, paragraph immediately following (1.7)]."
    ],
    "definitions_and_conventions": [
      "Subscripts indicate partial differentiation with respect to the indicated spatial or temporal variables [printed page 1, paragraph following (1.1)].",
